source("pre.R"); suppressPackageStartupMessages(library(bit64))
x <- int64(c(-2,-1,0,1,5)); b <- as.integer64(c(-2,-1,0,1,5))
show("cut zu", cut(x, c(-3,0,3,10))); show("cut bit64", cut(b, c(-3,0,3,10))); show("cut dbl", cut(c(-2,-1,0,1,5), c(-3,0,3,10)))
show("rowsum zu", rowsum(1:3, x[c(1,2,1)])); show("rowsum bit64", rowsum(1:3, b[c(1,2,1)]))
show("setdiff zu", setdiff(x, x[1])); show("setdiff b", setdiff(b, b[1])); show("setdiff zu,b", setdiff(x, b[1])); show("setdiff b,zu", setdiff(b, x[1]))
show("union zu", union(x, x[1])); show("intersect", intersect(x, x)); show("is.element", is.element(x[1], x)); show("setequal", setequal(x, rev(x)))
show("base::setdiff", base::setdiff(x, x[1]))
print(bit64::setdiff)
show("seq b", seq(as.integer64(10), as.integer64(1))); show("seq b 5", seq(as.integer64(5)))
show(":", x[1]:x[4]); show("matrix", matrix(x[1:4], 2)); show("%*%", x %*% x); show("array", array(x, 5))
show("is.double", is.double(x)); show("is.vector", is.vector(x))
show("colSums", colSums(data.frame(k=x)))
show("order 2 keys", order(x, x))
show("match zu in b", match(x, b)); show("match b in zu", match(b, x)); show("%in%", x %in% b[1:2]); show("b %in% zu", b %in% x[1:2])
show("match dbl in zu", match(c(-1, 5), x)); show("match zu in dbl", match(x, c(-1,5))); show("match zu in int", match(x, c(-1L,5L)));show("match chr", match("5", x))
show("table", table(x[c(1,1,2)])); show("table2", table(x[c(1,1,2)], c(1,2,1)))
show("rank", rank(x[c(3,1,NA,1)])); show("unique", unique(x[c(1,1,NA)]));
show("identical", identical(x, x)); show("identical x b", identical(x, b))
u <- uint64(c("18446744073709551614","5",NA)); i8 <- int128(c("-1","5",NA)); u8 <- uint128(c("7","5",NA))
for (w in list(u, i8, u8)) { cat("---", class(w)[1], "\n")
 show("match self", match(w, rev(w))); show("%in%", w %in% w[2]); show("order", order(w)); show("rank", rank(w)); show("table", table(w)); show("w:w", w[2]:w[2]); show("setdiff", setdiff(w, w[2])); show("union", union(w, w)); show("b + w", b[1:3] + w); show("w + b", w + b[1:3]); show("b == w", b[1:3] == w); show("w == b", w == b[1:3]); show("b < w", b[1:3] < w);show("c(b,w)", c(b[1:2], w)); show("c(w,b)", c(w, b[4:5])); show("as.integer64", as.integer64(w)); show("{b[2]<-w[2]}", {z <- b; z[2] <- w[2]; z}); show("{b[2]<-w[1]}", {z <- b; z[2] <- w[1]; z}); show("{w[2]<-b}", {z <- w; z[2] <- b[5]; z}); show("{w[1]<-b neg}", {z <- w; z[2] <- b[1]; z}); show("max(b,w)", max(b[4:5], w, na.rm=TRUE)); show("b %/% w", b[1:3] %/% w); show("b^w", b[1:3]^w[c(2,2,2)]); show("b & w", b[1:3] & w); show("identical", identical(w,w)); show("is.double", is.double(w)); show("matrix", matrix(w))
 show("seq", seq(w[2], w[2] + 2L)); show("summary", summary(w)); show("median", median(w, na.rm=TRUE)); show("is.vector", is.vector(w)); show("is.na(b[w?])", b[w[2]])
}
